public final class TwoPointers {

    private TwoPointers() {
    }

    public static boolean hasPairWithSum(int[] sortedValues, int target) {
        validateSortedInput(sortedValues);

        int left = 0;
        int right = sortedValues.length - 1;

        while (left < right) {
            int sum = sortedValues[left] + sortedValues[right];

            if (sum == target) {
                return true;
            }

            if (sum < target) {
                left++;
            } else {
                right--;
            }
        }

        return false;
    }

    private static void validateSortedInput(int[] sortedValues) {
        if (sortedValues == null) {
            throw new IllegalArgumentException("sortedValues must not be null");
        }

        for (int index = 1; index < sortedValues.length; index++) {
            if (sortedValues[index - 1] > sortedValues[index]) {
                throw new IllegalArgumentException(
                    "two-pointer search requires values sorted in nondecreasing order");
            }
        }
    }

    public static void main(String[] args) {
        int[] sortedValues = {-3, -1, 0, 1, 2};
        int target = -2;

        System.out.println(hasPairWithSum(sortedValues, target));
    }
}

public final class TwoPointersTest {

    private TwoPointersTest() {
    }

    public static void main(String[] args) {
        shouldFindMatchingPair();
        shouldReturnEmptyWhenNoPairExists();
        shouldRejectUnsortedInput();
        shouldHandleIntegerOverflowSafely();
    }

    private static void shouldFindMatchingPair() {
        TwoPointers.PairMatch match = TwoPointers.findPairWithSum(
            new int[] {-3, -1, 0, 1, 2},
            -2
        ).orElseThrow(() -> new AssertionError("Expected a matching pair"));

        assertEquals(0, match.leftIndex(), "left index");
        assertEquals(1, match.rightIndex(), "right index");
        assertEquals(-3, match.leftValue(), "left value");
        assertEquals(1, match.sum(), "pair sum");
    }

    private static void shouldReturnEmptyWhenNoPairExists() {
        if (TwoPointers.findPairWithSum(new int[] {1, 4, 8}, 6).isPresent()) {
            throw new AssertionError("Expected no matching pair");
        }
    }

    private static void shouldRejectUnsortedInput() {
        try {
            TwoPointers.findPairWithSum(new int[] {3, 1, 2}, 4);
            throw new AssertionError("Expected unsorted input to be rejected");
        } catch (IllegalArgumentException expected) {
            if (!expected.getMessage().contains("sorted")) {
                throw new AssertionError("Unexpected validation message: " + expected.getMessage());
            }
        }
    }

    private static void shouldHandleIntegerOverflowSafely() {
        TwoPointers.PairMatch match = TwoPointers.findPairWithSum(
            new int[] {-1, Integer.MAX_VALUE},
            Integer.MAX_VALUE - 1
        ).orElseThrow(() -> new AssertionError("Expected overflow-safe matching pair"));

        assertEquals(Integer.MAX_VALUE - 1L, match.sum(), "overflow-safe sum");
    }

    private static void assertEquals(long expected, long actual, String fieldName) {
        if (expected != actual) {
            throw new AssertionError(
                "Unexpected " + fieldName + ": expected " + expected + ", got " + actual);
        }
    }
}

import java.util.Optional;

public final class TwoPointers {

    private TwoPointers() {
    }

    public static Optional<PairMatch> findPairWithSum(int[] sortedValues, int target) {
        validateSortedInput(sortedValues);
        return findPairInSortedValues(sortedValues, target);
    }

    public static boolean hasPairWithSum(int[] sortedValues, int target) {
        return findPairWithSum(sortedValues, target).isPresent();
    }

    private static Optional<PairMatch> findPairInSortedValues(int[] sortedValues, int target) {
        int left = 0;
        int right = sortedValues.length - 1;

        while (left < right) {
            long sum = (long) sortedValues[left] + sortedValues[right];

            if (sum == target) {
                return Optional.of(new PairMatch(
                    left,
                    right,
                    sortedValues[left],
                    sortedValues[right]));
            }

            if (sum < target) {
                left++;
            } else {
                right--;
            }
        }

        return Optional.empty();
    }

    private static void validateSortedInput(int[] sortedValues) {
        if (sortedValues == null) {
            throw new IllegalArgumentException("sortedValues must not be null");
        }

        for (int index = 1; index < sortedValues.length; index++) {
            if (sortedValues[index - 1] > sortedValues[index]) {
                throw new IllegalArgumentException(
                    "two-pointer search requires values sorted in nondecreasing order");
            }
        }
    }

    public record PairMatch(int leftIndex, int rightIndex, int leftValue, int rightValue) {
        public long sum() {
            return (long) leftValue + rightValue;
        }
    }
}

